import { test, expect } from '@playwright/test';

test.describe('Form Submission in Modal Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-modal');
  });

  test('should submit form inside modal and display success feedback', async ({ page }) => {
    // Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Fill form fields using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john.doe@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message');

    // Verify all form fields are filled
    await expect(nameInput).toHaveValue('John Doe');
    await expect(emailInput).toHaveValue('john.doe@example.com');
    await expect(messageInput).toHaveValue('This is a test message');

    // Submit form using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success feedback appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify modal closes
    await expect(modal).not.toBeVisible();
  });

  test('should handle empty form submission and display error feedback', async ({ page }) => {
    // Open modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Fill form fields using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('');

    // Submit form using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error feedback appears
    const errorMessage = page.getByText('All fields are required');
    await expect(errorMessage).toBeVisible();

    // Verify modal still exists
    await expect(modal).toBeVisible();
  });
});
